import itertools
# shapes sets
S={k:set() for k in 'ABCDEF'}
for r in range(10):
    for c in range(10):
        if c<5:S['A'].add((r,c))
        else:S['F'].add((r,c))
        if (r<6 and c<5) or (r==6 and c<4) or (r==7 and c<3) or (r==8 and c<2) or (r==9 and c<1):S['B'].add((r,c))
        if c>=r:S['C'].add((r,c))
        if c<=r:S['D'].add((r,c))
        if c>=9-r:S['E'].add((r,c))
T={(r,c) for r in range(10) for c in range(10) if r<5 or c>=9-r}
# BFS last-write states per cell with stamps f/0
start=(0,)*100
seen={start}; frontier={start}; sol=None
for depth in range(1,9):
    nf=set()
    for st in frontier:
        for k in S:
            for col in [0,1]:
                ns=list(st)
                for r,c in S[k]:ns[r*10+c]=col
                ns=tuple(ns)
                if ns not in seen:
                    seen.add(ns);nf.add(ns)
                    if all(ns[r*10+c]==(1 if (r,c) in T else 0) for r in range(10) for c in range(10)):
                        print('sol',depth,k,col);sol=ns;break
                if sol:break
            if sol:break
        if sol:break
    if sol:break
    frontier=nf
    print(depth,len(seen))
print('found',bool(sol))
